create or replace package body stock_count_api as
  procedure record_count(p_sku in varchar2, p_counted in number) is
    l_reorder_point number;
    l_existing_requests number;
  begin
    update inventory_levels 
    set on_hand = p_counted 
    where sku = p_sku
    returning reorder_point into l_reorder_point;

    select count(*) 
    into l_existing_requests 
    from reorder_requests 
    where sku = p_sku;

    if p_counted <= l_reorder_point and l_existing_requests = 0 then
      insert into reorder_requests (sku) values (p_sku);
    end if;
  end record_count;

  function open_requests(p_sku in varchar2) return number is
    l_count number;
  begin
    select count(*) into l_count from reorder_requests where sku = p_sku;
    return l_count;
  end open_requests;
end stock_count_api;
